CREATE TABLE professional_profiles (user_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', profession TEXT NOT NULL DEFAULT 'unassigned', active INTEGER NOT NULL DEFAULT 1, rpps TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE care_teams (id TEXT PRIMARY KEY, label TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE professional_teams (user_id TEXT NOT NULL, team_id TEXT NOT NULL, valid_from TEXT NOT NULL, valid_until TEXT, PRIMARY KEY(user_id,team_id));
CREATE TABLE stay_teams (stay_id TEXT NOT NULL, team_id TEXT NOT NULL, valid_from TEXT NOT NULL, valid_until TEXT, PRIMARY KEY(stay_id,team_id));
CREATE TABLE professional_access_log (sequence INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, result TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '');
CREATE INDEX professional_access_actor ON professional_access_log(actor,sequence DESC);
CREATE INDEX professional_access_target ON professional_access_log(target,sequence DESC);
CREATE TABLE professional_policy_revision (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 1);
INSERT INTO professional_policy_revision(id,revision) VALUES(1,1);
CREATE TABLE file_scopes (hash TEXT NOT NULL, document_key TEXT NOT NULL, PRIMARY KEY(hash,document_key));
CREATE TABLE access_migrations (id TEXT PRIMARY KEY);
CREATE TRIGGER professional_profiles_insert AFTER INSERT ON professional_profiles BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER professional_profiles_update AFTER UPDATE ON professional_profiles BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER professional_teams_insert AFTER INSERT ON professional_teams BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER professional_teams_update AFTER UPDATE ON professional_teams BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER stay_teams_insert AFTER INSERT ON stay_teams BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER stay_teams_update AFTER UPDATE ON stay_teams BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER care_teams_update AFTER UPDATE ON care_teams BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER professional_access_no_update BEFORE UPDATE ON professional_access_log BEGIN SELECT RAISE(ABORT,'Access audit is immutable'); END;
CREATE TRIGGER professional_access_no_delete BEFORE DELETE ON professional_access_log BEGIN SELECT RAISE(ABORT,'Access audit is immutable'); END;
